pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint256 newValue) public {
        // Restrict to a reasonable range to keep the input space wide but meaningful
        uint256 initial = c.winnersPerPeriod();
        vm.prank(address(this));
        c.adjustAdminAccess(address(this), true);
        vm.prank(address(this));
        c.updateWinnersPerPeriod(newValue);
        if (newValue == initial) {
            // If newValue equals the current value, the property trivially holds even without the update.
            // We need to test mutation, so we skip this case to let the fuzzer find a differing value.
            assertEq(c.winnersPerPeriod(), initial);
        } else {
            // The reference contract must set winnersPerPeriod to newValue.
            // The buggy contract does nothing, so winnersPerPeriod stays at initial.
            assertEq(c.winnersPerPeriod(), newValue);
        }
    }
}

