pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    function testFuzz_property(uint256 newAmount, address admin, address other) public {
        vm.assume(admin != address(0) && other != address(0) && admin != other);
        vm.assume(newAmount > 0);

        // Give both admin and other admin rights
        c.adjustAdminAccess(admin, true);
        c.adjustAdminAccess(other, true);

        uint256 oldValue = c.winnersPerPeriod();

        // admin calls updateWinnersPerPeriod with newAmount
        vm.prank(admin);
        c.updateWinnersPerPeriod(newAmount);

        // other calls pickWinner, which will succeed only if newAmount == winnersPerPeriod
        // We need an array of token IDs. The fuzzer supplies IDs; we just need length == winnersPerPeriod.
        // Since we don't have actual tokens, we construct a winners array of the expected length.
        uint256[] memory winners = new uint256[](newAmount);
        // Fill with arbitrary IDs
        for (uint256 i = 0; i < newAmount; i++) {
            winners[i] = i + 1;
        }

        // Now call pickWinner. For the reference, winnersPerPeriod == newAmount, so it should not revert (assuming other invariants like isSelectionComplete[roundId] false etc hold).
        // For the mutant, winnersPerPeriod unchanged (still oldValue), so length mismatch and revert.
        bool ok = true;
        vm.prank(other);
        try c.pickWinner(winners) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference succeeds for any newAmount > 0, while mutant fails when oldValue != newAmount.
        assertTrue(ok);
    }
}

