pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint256[2] calldata winners) public {
        // restrict winners to be non-zero addresses (valid token IDs)
        vm.assume(winners[0] != 0 || winners[1] != 0);
        vm.assume(winners[0] != winners[1]);

        // setup: make this contract an admin so it can call pickWinner
        c.adjustAdminAccess(address(this), true);
        // set winnersPerPeriod to 2 to match our winners length
        c.updateWinnersPerPeriod(2);

        // perform one pickWinner call
        uint256[] memory w = new uint256[](2);
        w[0] = winners[0];
        w[1] = winners[1];
        c.pickWinner(w);

        // record roundId after first call
        uint256 roundIdAfter1 = c.roundId();

        // attempt a second call with the same winners; this should fail on reference because roundId was incremented by 1 and isSelectionComplete[1] is false, but on mutant roundId becomes 2 and isSelectionComplete[2] is false, allowing the call to succeed without revert.
        bool ok;
        try c.pickWinner(w) { ok = true; } catch { ok = false; }

        // For the reference contract, the second call must revert because roundId was increased by 1, so isSelectionComplete[0] is now true and new roundId is 1 which is not selection-complete yet. For the mutant, roundId increased by 2, so roundId=2 is not selection-complete, and the call succeeds.
        // The invariant: after one successful pickWinner, the next call with identical parameters must revert.
        assertTrue(!ok);
    }
}

